// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/git/WorktreesShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * The session Worktrees dialog (src/grid/WorktreesPanel.tsx, opened by the
 * FolderGit2 button of src/grid/Worktrees.tsx) as static scene markup, open
 * over the grid of the Tasks race: the web session's repository with the
 * race's three worktrees beside merged, unmerged and dirty ones. The rows,
 * the facets, the status line and the actions are what the panel renders for
 * that state; only the data is fixed.
 */
import { FolderGit2, GitBranch, GitMerge, GitPullRequestCreateArrow, Info, ListTodo, RefreshCw, Search, SlidersHorizontal, Trash2, type LucideIcon } from "lucide-react";
import { AnsiScreen } from "../../home/ansi";
import { Term, Tile } from "../../home/AppUI";
import { Shot, THIS_MAC } from "../../home/Chrome";
import { ActiveCanvas } from "../../home/Interactive";
import { AppWindow, SessionTile, TASK_SLUG, WIN_SIZE } from "../../home/Scenes";
import { Modal, windowViewport } from "./Modal";
import { compactPath } from "./TileFooter";

type MergeKind = "ancestor" | "squash" | "patch";

interface Worktree {
  path: string;
  branch: string;
  merged: boolean;
  mergedBy: MergeKind | null;
  dirty: boolean;
  /** A tile works in it (the race's attempts in the grid behind). */
  open: boolean;
  task: string | null;
}

interface Repo {
  root: string;
  base: string;
  worktrees: Worktree[];
}

const MERGE_LABELS: Record<MergeKind, string> = { ancestor: "Merged", squash: "Squash-merged", patch: "Rebase-merged" };
const TASK_TITLE = "Add search to the notes page";

/* The card frames the dialog (860 x 720, centred on the 1440 x 900 window, so
   at x 290..1150, y 90..810) with about 33px around it, and its edges fall in
   gaps of the grid behind: the left and right ones in the column gaps of a
   243px | 1fr | 243px grid (x 253..263 and 1177..1187), the top one in the
   blank upper part of the first row's headers (they start at y 53, their text
   at about 61), the bottom one between two lines of the second row's
   bottom-aligned terminals (857 - 15 = 842). */
const FRAME = { left: 258, top: 56, right: 1182, bottom: 842 };
const W = FRAME.right - FRAME.left;
const H = FRAME.bottom - FRAME.top;

const worktree = (name: string, rest: Partial<Worktree> = {}): Worktree => ({
  path: `~/fieldnotes/web.worktrees/${name}`,
  branch: `pzza/${name}`,
  merged: false,
  mergedBy: null,
  dirty: false,
  open: false,
  task: null,
  ...rest,
});

const ATTEMPTS = ([1, 2, 3] as const).map((n) => ({ name: `${TASK_SLUG}-claude-${n}`, capture: `att-${n}` as const }));

// `git worktree list` order: the worktrees folder's entries by name. Ten rows
// fill the dialog's list.
const REPO: Repo = {
  root: "~/fieldnotes/web",
  base: "main",
  worktrees: [
    ...ATTEMPTS.map(({ name }) => worktree(name, { dirty: true, open: true, task: TASK_TITLE })),
    worktree("export-markdown", { dirty: true }),
    worktree("fix-note-dates", { merged: true, mergedBy: "squash" }),
    worktree("markdown-preview"),
    worktree("note-tags", { merged: true, mergedBy: "ancestor" }),
    worktree("offline-drafts"),
    worktree("pinned-notes", { merged: true, mergedBy: "patch" }),
    worktree("sync-conflicts"),
  ],
};

const folderName = (path: string) => path.split("/").filter(Boolean).pop() ?? path;
const plural = (count: number, one: string, many = `${one}s`) => `${count.toLocaleString()} ${count === 1 ? one : many}`;

// The panel's blocker, for a session that works in the main checkout.
const blocker = (item: Worktree): string | null => (item.open ? "A tile is working in it" : item.dirty ? "Has uncommitted changes" : null);

function WorktreesDialog() {
  const repo = REPO;
  const total = repo.worktrees.length;
  const removable = repo.worktrees.filter((item) => item.merged && !blocker(item));
  const counts = { all: total, open: repo.worktrees.filter((item) => !item.merged).length, merged: repo.worktrees.filter((item) => item.merged).length };
  return (
    <Modal title="Worktrees" icon={FolderGit2} size="xl" className="wtm-modal">
      <div className="wtm">
        <div className="as-bar">
          <label className="as-search">
            <Search size={14} aria-hidden="true" />
            <input type="search" defaultValue="" placeholder="Search branches, folders or tasks" aria-label="Search worktrees" autoComplete="off" spellCheck={false} />
          </label>
          {removable.length ? (
            <button type="button" className="btn btn-sm" title="Removes every merged worktree no tile works in, with its merged branch">
              <Trash2 size={13} aria-hidden="true" />
              Clean up {removable.length} merged
            </button>
          ) : null}
          <button type="button" className="icon-btn" title="Read again" aria-label="Read again" aria-busy={false}>
            <span className="icon-inner">
              <RefreshCw size={14} strokeWidth={1.9} />
            </span>
          </button>
        </div>
        <div className="as-agents" role="group" aria-label="Show">
          {(
            [
              ["all", "All"],
              ["open", "Not merged"],
              ["merged", "Merged"],
            ] as const
          ).map(([id, label]) => (
            <button key={id} type="button" className={`as-chip ${id === "all" ? "on" : ""}`} aria-pressed={id === "all"}>
              {label}
              <span className="as-chip-count">{counts[id].toLocaleString()}</span>
            </button>
          ))}
        </div>

        <div className="as-status" aria-live="polite">
          <span>
            <strong>{plural(total, "worktree")}</strong> in <span title={repo.root}>{compactPath(repo.root)}</span> on {THIS_MAC.name}
          </span>
        </div>

        <div className="wtm-list">
          <section className="wtm-repo" aria-label={`${folderName(repo.root)}, ${plural(total, "worktree")}`}>
            <div className="wtm-repo-head">
              <FolderGit2 size={13} className="wtm-repo-icon" aria-hidden="true" />
              <span className="wtm-repo-name">{folderName(repo.root)}</span>
              <span className="wtm-repo-path" title={repo.root}>
                {compactPath(repo.root)}
              </span>
              <span className="as-badge wtm-repo-base" title={`Worktrees merge into ${repo.base}`}>
                <GitBranch size={10} aria-hidden="true" />
                {repo.base}
              </span>
              <span className="wtm-repo-count">{total.toLocaleString()}</span>
              <button type="button" className="wtm-setup-toggle" aria-expanded={false} aria-haspopup="dialog" title="Setup for new worktrees: files to copy and commands to run before the agent">
                <SlidersHorizontal size={12} aria-hidden="true" />
                Setup
              </button>
            </div>
            {repo.worktrees.map((item) => (
              <WorktreeRow key={item.path} repo={repo} worktree={item} blocked={blocker(item)} />
            ))}
          </section>
        </div>

        <footer className="as-foot">
          <div className="as-foot-info" aria-live="polite">
            <span className="as-reason">
              <Info size={13} aria-hidden="true" />
              Start an agent in a new worktree with Worktree in New session. Merged worktrees can be removed with their branch.
            </span>
          </div>
        </footer>
      </div>
    </Modal>
  );
}

function WorktreeRow({ repo, worktree, blocked }: { repo: Repo; worktree: Worktree; blocked: string | null }) {
  const merge = worktree.merged ? `${MERGE_LABELS[worktree.mergedBy ?? "ancestor"]} into ${repo.base}` : "Not merged";
  const label = worktree.branch;
  const task = worktree.task;
  const viaTask = task ? `Part of the task "${task}": opens its land checks` : null;
  const mergeWhy = worktree.merged ? `it is already in ${repo.base}` : worktree.dirty && !task ? "it has uncommitted changes" : null;
  const Icon = worktree.merged ? GitMerge : GitBranch;
  return (
    <div className="wtm-row">
      <span className={`wtm-row-icon${worktree.merged ? " is-merged" : ""}`} aria-hidden="true">
        <Icon size={15} />
      </span>
      <span className="wtm-row-main">
        <span className="wtm-row-head">
          <span className="wtm-row-title" title={worktree.branch}>
            {worktree.branch}
          </span>
          {task ? (
            <span className="as-badge wtm-task" title={`Task: ${task}`}>
              <ListTodo size={10} aria-hidden="true" />
              {task}
            </span>
          ) : null}
        </span>
        <span className="wtm-row-meta" title={[merge, blocked, worktree.path].filter(Boolean).join(" · ")}>
          <span className={worktree.merged ? "wtm-merged" : undefined}>{merge}</span>
          {blocked ? <span className="wtm-blocker">{blocked}</span> : null}
          <span className="wtm-row-path">{compactPath(worktree.path)}</span>
        </span>
      </span>
      <span className="wtm-row-actions">
        <RowAction icon={GitPullRequestCreateArrow} text="Open PR" label={viaTask ?? `Push ${worktree.branch} and open a pull request`} ariaLabel={`Open pull request for ${label}`} reason={null} />
        <RowAction
          icon={GitMerge}
          text="Merge"
          label={viaTask ?? `Merge into ${repo.base} in the main checkout`}
          ariaLabel={`Merge ${label} into ${repo.base}`}
          reason={mergeWhy ? `Can't merge: ${mergeWhy}` : null}
        />
        <RowAction
          icon={Trash2}
          danger
          label={worktree.merged ? "Remove the folder and its merged branch" : "Remove the folder (the unmerged branch is kept)"}
          ariaLabel={`Remove worktree ${label}`}
          reason={blocked ? `Can't remove: ${blocked.toLowerCase()}` : null}
        />
      </span>
    </div>
  );
}

// A row button that stays focusable and explains itself when it cannot run.
function RowAction({ icon: Icon, text, label, ariaLabel, reason, danger = false }: { icon: LucideIcon; text?: string; label: string; ariaLabel: string; reason: string | null; danger?: boolean }) {
  const blocked = reason !== null;
  return (
    <button
      type="button"
      className={`wtm-btn${text ? " has-text" : ""}${danger ? " is-danger" : ""}${blocked ? " is-blocked" : ""}`}
      aria-disabled={blocked || undefined}
      title={reason ?? label}
      aria-label={ariaLabel}
    >
      <Icon size={12} aria-hidden="true" />
      {text ? <span>{text}</span> : null}
    </button>
  );
}

export function WorktreesShot() {
  return (
    <Shot id="tasks" width={W} height={H}>
      {/* The dialog sizes against the window, as it does against the app's viewport. */}
      <div style={{ display: "contents", ...windowViewport(WIN_SIZE.width, WIN_SIZE.height) }}>
        <AppWindow box={{ left: -FRAME.left, top: -FRAME.top, ...WIN_SIZE }}>
          <ActiveCanvas
            initial={3}
            style={{ gridTemplateColumns: "243px 1fr 243px", gridTemplateRows: "1fr 1fr" }}
            tiles={[
              // The race's three attempts, each working in its own worktree.
              ...ATTEMPTS.map(({ name, capture }, i) => (
                <Tile
                  key={name}
                  title={name}
                  agent="claude"
                  stat="notify"
                  kbd={`⌘${i + 1}`}
                  device={THIS_MAC}
                  strip={{ session: name, branch: `pzza/${name}`, dirty: true, worktree: true, path: `~/fieldnotes/web.worktrees/${name}` }}
                >
                  <Term>
                    <AnsiScreen id={capture} />
                  </Term>
                </Tile>
              )),
              // The web session in the main checkout, which opened the dialog.
              <SessionTile key="web" id="web" capture="web-57" kbd="⌘4" />,
              <SessionTile key="docs" id="docs" capture="docs-57" kbd="⌘5" />,
              <SessionTile key="release" id="release" capture="release-57" kbd="⌘6" />,
            ]}
          />
          <WorktreesDialog />
        </AppWindow>
      </div>
    </Shot>
  );
}
